/**
 * Ensures the three migration sources stay in sync:
 *   1. drizzle/*.sql (generated by drizzle-kit)
 *   2. src-tauri/migrations/*.sql (embedded in the binary)
 *   3. include_str! entries in src-tauri/src/lib.rs
 *
 * Usage: node scripts/check-migrations.mjs (also wired into CI)
 */
import { readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

const root = fileURLToPath(new URL("..", import.meta.url));
const drizzleDir = join(root, "drizzle");
const embeddedDir = join(root, "src-tauri", "migrations");
const libRs = join(root, "src-tauri", "src", "lib.rs");

const drizzle = readdirSync(drizzleDir).filter((f) => f.endsWith(".sql")).sort();
const embedded = readdirSync(embeddedDir).filter((f) => f.endsWith(".sql")).sort();
const libSrc = readFileSync(libRs, "utf8");
const includes = [...libSrc.matchAll(/include_str!\(\s*"[^"]*migrations\/([^"]+)"\s*\)/g)].map((m) => m[1]).sort();

let failed = false;
function check(label, a, b) {
  const missing = a.filter((f) => !b.includes(f));
  const extra = b.filter((f) => !a.includes(f));
  if (missing.length === 0 && extra.length === 0) {
    console.log(`ok ${label}: ${a.length} files`);
    return;
  }
  failed = true;
  for (const f of missing) console.error(`error ${label}: missing ${f}`);
  for (const f of extra) console.error(`error ${label}: extra ${f}`);
}

check("drizzle ↔ src-tauri/migrations", drizzle, embedded);
check("src-tauri/migrations ↔ lib.rs include_str", embedded, includes);

if (failed) {
  console.error("\nMigration sources out of sync. Run pnpm db:generate && pnpm db:sync, then add the new Migration entry to migrations() in src-tauri/src/lib.rs.");
  process.exit(1);
}
